import collections
import pandas as pd

def task_func(my_tuple, path_csv_files):
    if isinstance(my_tuple, (str, bytes)):
        columns = [my_tuple]
    else:
        try:
            columns = list(my_tuple)
        except TypeError:
            columns = [my_tuple]

    if isinstance(path_csv_files, (str, bytes)):
        csv_files = [path_csv_files]
    else:
        try:
            csv_files = list(path_csv_files)
        except TypeError:
            csv_files = [path_csv_files]

    result = {column: collections.Counter() for column in columns}

    for csv_file in csv_files:
        try:
            df = pd.read_csv(csv_file)
        except Exception:
            continue

        for column in columns:
            if column not in df.columns:
                continue
            values = df[column].dropna().tolist()
            if values:
                result[column].update(values)

    return {column: dict(counter) for column, counter in result.items()}
